    dict(id="CCS-FAQ", titulo="CCS: preguntas frecuentes del seguro de riesgos extraordinarios", organismo="Consorcio de Compensación de Seguros", url="https://www.consorseguros.es/preguntas-frecuentes/seguros-de-riesgos-extraodinarios", tipo="recomendacion-tecnica", jurisdiccion="ES", version="consultado 26/11/2026", autoridad="alta", vigencia="vigente", estado="validated", nota="Franquicia del 7 % de los daños indemnizables en bienes; no se aplica a vehículos con póliza de automóviles, viviendas ni comunidades de propietarios de viviendas. Desde julio de 2016 las pólizas de automóvil solo de RC también llevan recargo. Contrastado con el condicionado de Chubb."),
    dict(id="LOSSEAR-ART99", titulo="Ley 20/2015, de ordenación, supervisión y solvencia de las entidades aseguradoras y reaseguradoras, art. 99", organismo="BOE", url="https://www.boe.es/eli/es/l/2015/07/14/20/con", tipo="obligacion-legal", jurisdiccion="ES", version="consolidado (fecha no visible; leído el 26/11/2026)", autoridad="alta", vigencia="vigente", estado="draft", nota="Art. 99.2: las aseguradoras pueden tratar datos de salud sin consentimiento para determinar la asistencia sanitaria y la indemnización que deban pagar, informando al interesado. Habilita a las aseguradoras, no a los mediadores. Una sola lectura del BOE."),
    dict(id="LOPDGDD-DA17", titulo="Ley Orgánica 3/2018 (LOPDGDD), disposición adicional decimoséptima: tratamientos de datos de salud", organismo="BOE", url="https://www.boe.es/eli/es/lo/2018/12/05/3/con", tipo="obligacion-legal", jurisdiccion="ES", version="consolidado (BOE-A-2018-16673)", autoridad="alta", vigencia="vigente", estado="draft", nota="Los tratamientos de datos de salud regulados en las leyes que enumera, entre ellas la Ley 20/2015, se amparan en el art. 9.2 g), h), i) y j) del RGPD. Falta leer el texto en el BOE."),
    dict(id="AEPD-CORREDOR-2018", titulo="AEPD, informe 2018-0151: el corredor de seguros es responsable del tratamiento", organismo="AEPD", url="https://www.aepd.es/documento/2018-0151.pdf", tipo="recomendacion-tecnica", jurisdiccion="ES", version="2018", autoridad="alta", vigencia="vigente", estado="validated", nota="Base en el art. 6.1 b) y c) del RGPD. No trata datos de salud. Coincide con el informe 2017-0232 de la AEPD sobre el anteproyecto de distribución."),
